      field(field,profile){const key=APP.modal.esc(field.key),label=APP.modal.esc(field.label||''),value=APP.modal.esc(profile?.[field.key]??field.value??''),placeholder=APP.modal.esc(field.placeholder||''),maximum=Number.isFinite(Number(field.maxLength))?` maxlength="${Math.max(1,Math.round(Number(field.maxLength)))}"`:'';if(field.multiline)return `<label class="editor-field"><span class="editor-field-label">${label}</span><textarea class="editor-input global-profile-textarea" data-social-field="${key}" placeholder="${placeholder}" autocomplete="off" spellcheck="false"${maximum}>${value}</textarea></label>`;return `<label class="editor-field"><span class="editor-field-label">${label}</span><input class="editor-input" data-social-field="${key}" value="${value}" placeholder="${placeholder}" autocomplete="off" spellcheck="false"${maximum}></label>`},
