      async imageData(file,kind='cover'){if(!file?.type?.startsWith('image/'))throw new Error('请选择图片文件');let source=null,revoke='';try{if(typeof createImageBitmap==='function')source=await createImageBitmap(file);else{revoke=URL.createObjectURL(file);source=new Image();source.src=revoke;await source.decode()}const width=source.width||source.naturalWidth,height=source.height||source.naturalHeight;if(!width||!height)throw new Error('图片尺寸无效');const square=kind==='avatar',limit=square?320:720;let sx=0,sy=0,sw=width,sh=height;if(square){const side=Math.min(width,height);sx=(width-side)/2;sy=(height-side)/2;sw=side;sh=side}const scale=Math.min(1,limit/(square?sw:Math.max(sw,sh))),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(sw*scale));canvas.height=Math.max(1,Math.round(sh*scale));const context=canvas.getContext('2d');if(!context)throw new Error('无法创建图片画布');context.drawImage(source,sx,sy,sw,sh,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',square?.82:.76)}finally{if(revoke)URL.revokeObjectURL(revoke);source?.close?.()}},
